          },
        },
      },
    },
  },
  agents: {
    label: 'Agents',
    default: 'some',
    states: {
      none: { label: 'None connected', db: { agents: { $set: [] } } },
      some: { label: 'Two connected', db: {} },
      many: { label: '14 connected', db: { agents: { $set: manyAgents } } },
