import { useState } from 'react';
import { money, send, useApi, type Payment, type User } from '../api';

export function Payments({ me }: { me: User | null }) {
  const { data, error, loading } = useApi<Payment[]>('/api/payments');
  const [actionError, setActionError] = useState<string | null>(null);
  const act = async (id: string, verb: 'approve' | 'reject') => {
    setActionError(null);
    try {
      await send('POST', `/api/payments/${id}/${verb}`);
    } catch (e) {
      setActionError((e as Error).message);
    }
  };
  if (error) return <p className="error" data-testid="payments-error">Payments are unavailable: {error}</p>;
  if (loading && !data) return <p className="muted">Loading payments…</p>;
  const pending = data?.filter((p) => p.status === 'pending_approval') ?? [];
  return (
    <>
      <h1>Payments</h1>
      {actionError && <p className="error">{actionError}</p>}
      {pending.length > 0 && (
        <section className="card" data-testid="approvals">
          <h2>Waiting for approval ({pending.length})</h2>
          <ul className="list">
            {pending.map((p) => (
              <li key={p.id}>
                <span>{p.vendor}</span>
                <span className="num">{money(p.amount)}</span>
                {me?.role === 'admin' ? (
                  <span className="actions">
                    <button className="btn" onClick={() => act(p.id, 'approve')}>Approve</button>
                    <button className="btn btn--ghost" onClick={() => act(p.id, 'reject')}>Reject</button>
                  </span>
                ) : (
                  <span className="muted">Waiting for an admin</span>
                )}
              </li>
            ))}
          </ul>
        </section>
      )}
      <section className="card">
        <h2>All payments</h2>
        <ul className="list" data-testid="payments">
          {data?.map((p) => (
            <li key={p.id}>
              <span>{p.vendor}</span>
              <span className="muted">{p.date}</span>
              <span className={`pill pill--${p.status}`}>{p.status.replace('_', ' ')}</span>
              <span className="num">{money(p.amount)}</span>
            </li>
          ))}
        </ul>
      </section>
    </>
  );
}
import { useCallback, useEffect, useState } from 'react';
import { useMockDbVersion } from '@stagecraft/react';

/** Agents live on a separate API host in this app, to show cross-origin mocking. */
export const AGENTS_API = 'https://api.ledgerly.example';

export interface User { id: string; name: string; email: string; role: string; onboardingStep: number }
export interface Account { id: string; name: string; status: 'active' | 'frozen' | 'over_limit' | 'under_review'; balance: number; monthlyLimit: number; spentThisMonth: number }
export interface Payment { id: string; vendor: string; amount: number; status: string; requestedBy: string; date: string }
export interface Agent { id: string; name: string; scope: string; spendLimit: number; status: string }

export function useApi<T>(url: string) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const dbVersion = useMockDbVersion();
  const [nonce, setNonce] = useState(0);
  useEffect(() => {
    let live = true;
    setLoading(true);
    fetch(url)
      .then(async (r) => {
        const body = await r.json().catch(() => null);
        if (!r.ok) throw new Error(body?.error ?? `Request failed (${r.status})`);
        return body as T;
      })
      .then((d) => live && (setData(d), setError(null)))
      .catch((e: Error) => live && setError(e.message))
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, [url, dbVersion, nonce]);
  const reload = useCallback(() => setNonce((n) => n + 1), []);
  return { data, error, loading, reload };
}

export async function send<T>(method: string, url: string, body?: unknown): Promise<T> {
  const r = await fetch(url, { method, headers: { 'content-type': 'application/json' }, body: body ? JSON.stringify(body) : undefined });
  const data = await r.json().catch(() => null);
  if (!r.ok) throw new Error(data?.error ?? `Request failed (${r.status})`);
  return data as T;
}

